<?php
require dirname(__DIR__).'/config.php';admin_required();$pdo=db();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'){$s=$pdo->prepare("DELETE FROM categories WHERE id=?");$s->execute([$id]);flash('Category deleted.');header('Location: categories.php');exit;}else{$name=trim($_POST['name']??'');$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$_POST['slug']?:$name),'-'));$active=isset($_POST['active'])?1:0;$sort=(int)($_POST['sort_order']??0);if($name==='')$error='Category name is required.';else{try{if($id){$s=$pdo->prepare("UPDATE categories SET name=?,slug=?,sort_order=?,active=? WHERE id=?");$s->execute([$name,$slug,$sort,$active,$id]);}else{$s=$pdo->prepare("INSERT INTO categories(name,slug,sort_order,active) VALUES(?,?,?,?)");$s->execute([$name,$slug,$sort,$active]);}flash('Category saved.');header('Location: categories.php');exit;}catch(Throwable $e){$error='That category slug already exists.';}}}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM categories WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$cats=$pdo->query("SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name")->fetchAll();$form=$edit||isset($_GET['new'])||$error;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categories — Aastha Admin</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="admin-shell"><aside class="sidebar"><a class="admin-brand" href="index.php"><span>A</span><b>Aastha<small>ADMIN PANEL</small></b></a><div class="side-label">MAIN MENU</div><a class="side-link" href="index.php"><i>▦</i> Dashboard</a><a class="side-link" href="orders.php"><i>☷</i> Orders</a><a class="side-link" href="products.php"><i>▣</i> Products</a><a class="side-link active" href="categories.php"><i>▤</i> Categories</a><a class="side-link" href="customers.php"><i>♙</i> Customers</a><a class="side-link" href="settings.php"><i>⚙</i> Store settings</a><div class="side-bottom"><a class="side-link" href="../index.php"><i>↗</i> View storefront</a><a class="side-link" href="logout.php"><i>⇥</i> Logout</a></div></aside><main class="admin-main"><header class="admin-topbar"><button class="mobile-menu" data-menu>☰</button><div class="crumb">Home <span>›</span> Categories</div><div class="admin-user"><span class="avatar">A</span><?=e($_SESSION['admin_name']??'Admin')?> <a href="logout.php">Logout ↗</a></div></header><section class="admin-content"><div class="page-title-row"><div><h1>Categories</h1><p>Organise your store catalogue</p></div><a class="btn primary" href="categories.php?new=1">＋ Add category</a></div><?php show_flash();if($error): ?><div class="notice error"><?=e($error)?></div><?php endif; ?><?php if($form):$v=$edit??[]; ?><form class="panel edit-form" method="post"><div class="panel-head"><h2><?=$edit?'Edit category':'Add category'?></h2></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($v['id']??0)?>"><div class="form-grid"><label>Category name<input name="name" required value="<?=e($v['name']??'')?>"></label><label>URL slug<input name="slug" placeholder="auto-generated from name" value="<?=e($v['slug']??'')?>"></label><label>Sort order<input type="number" name="sort_order" value="<?=e((string)($v['sort_order']??0))?>"></label><label class="check-label"><input type="checkbox" name="active" <?=(!isset($v['active'])||$v['active']?'checked':'')?>> Visible on storefront</label></div><div class="form-actions"><button class="btn primary">Save category</button><a class="btn pale" href="categories.php">Cancel</a></div></form><?php endif; ?><section class="panel"><div class="panel-head"><h2>Category list</h2><span class="muted"><?=count($cats)?> categories</span></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>Slug</th><th>Products</th><th>Sort order</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($cats as $c): ?><tr><td><b><?=e($c['name'])?></b></td><td><?=e($c['slug'])?></td><td><?=$c['product_count']?></td><td><?=$c['sort_order']?></td><td><span class="status <?=($c['active']?'status-delivered':'status-cancelled')?>"><?=($c['active']?'Active':'Hidden')?></span></td><td><a class="table-action" href="categories.php?edit=<?=(int)$c['id']?>">Edit</a><form class="inline-form" method="post" data-confirm="Delete category? Products will become uncategorised."><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="text-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></section></main></div><script src="../assets/js/admin.js"></script></body></html>